import{_ as r,o as e,c as i,a2 as n}from"./chunks/framework.CCtxZRER.js";const m=JSON.parse('{"title":"Riwayat Versi","description":"Catatan perubahan handbook dari versi ke versi.","frontmatter":{"title":"Riwayat Versi","description":"Catatan perubahan handbook dari versi ke versi.","status":"ditinjau","diperbarui":"2026-10-13T00:00:00.000Z","kategori":"Tentang Handbook","kata_kunci":["versi","riwayat","changelog","perubahan"]},"headers":[],"relativePath":"tentang-handbook/riwayat-versi.md","filePath":"tentang-handbook/riwayat-versi.md"}'),t={name:"tentang-handbook/riwayat-versi.md"};function o(s,a,l,u,d,k){return e(),i("div",null,[...a[0]||(a[0]=[n('<h1 id="riwayat-versi" tabindex="-1">Riwayat Versi <a class="header-anchor" href="#riwayat-versi" aria-label="Permalink to &quot;Riwayat Versi&quot;">​</a></h1><p class="lead">Setiap perubahan penting dicatat di sini. Nomor versi juga tercantum di menu atas dan di <code>package.json</code>.</p><h2 id="v0-2-1-13-oktober-2026" tabindex="-1">v0.2.1 (13 Oktober 2026) <a class="header-anchor" href="#v0-2-1-13-oktober-2026" aria-label="Permalink to &quot;v0.2.1 (13 Oktober 2026)&quot;">​</a></h2><ul><li><strong>Tempat foto di setiap kotak flowchart</strong> barang masuk dan barang keluar, termasuk kotak &quot;Tidak&quot;. Selama foto belum ada, yang tampil placeholder.</li><li>Kotak flowchart diberi nomor yang sama dengan kartu langkah. Kotak bernomor bisa diklik untuk melompat ke kartu fotonya.</li><li>Langkah dipecah agar satu kotak flowchart sama dengan satu kartu: barang masuk 10 langkah, barang keluar 11 langkah.</li><li>Daftar nama file foto dan statusnya ada di halaman Cara Memperbarui Handbook.</li></ul><h2 id="v0-2-0-13-oktober-2026" tabindex="-1">v0.2.0 (13 Oktober 2026) <a class="header-anchor" href="#v0-2-0-13-oktober-2026" aria-label="Permalink to &quot;v0.2.0 (13 Oktober 2026)&quot;">​</a></h2><p>Tampilan dibuat lebih sederhana dan ramah, serta alur kerja disesuaikan dengan alur asli Gudang Teknik.</p><ul><li><strong>Alur barang masuk dan barang keluar</strong> sekarang mengikuti diagram presentasi dan catatan alur proses Gudang Teknik (ERP, rak reservasi, catatan manual rak, surat tanda terima, laporan ke OS/PPIC).</li><li><strong>Flowchart baru</strong>: alur warehouse lengkap, barang masuk, dan barang keluar, berwarna sesuai pelaku, ditambah daftar langkah bernomor.</li><li><strong>Beranda baru</strong>: kolom pencarian, enam topik utama, dan tiga langkah untuk peserta baru.</li><li><strong>Lebih sederhana</strong>: label status, catatan kaki sumber, tombol kata kunci, filter FAQ, tabel identitas SOP, dan menu versi dihapus dari tampilan. Menu atas tinggal empat.</li><li><strong>Font Plus Jakarta Sans</strong>, sudut kartu lebih bulat, dan bahasa disapa dengan &quot;kamu&quot;.</li><li>SOP Penerimaan dan Pengeluaran Barang ditulis ulang sesuai alur asli. FAQ dan Kamus Istilah ditambah (ERP, OS/PPIC, rak reservasi, surat tanda terima, catatan manual rak).</li></ul><h2 id="v0-1-0-13-oktober-2026" tabindex="-1">v0.1.0 (13 Oktober 2026) <a class="header-anchor" href="#v0-1-0-13-oktober-2026" aria-label="Permalink to &quot;v0.1.0 (13 Oktober 2026)&quot;">​</a></h2><p>Versi awal untuk ditinjau pembimbing.</p><ul><li>Struktur website: Beranda, Profil Perusahaan, Gudang Teknik, Alur Kerja, Tutorial, SOP, FAQ, Referensi, dan halaman 404.</li><li>Profil perusahaan dari sumber publik, dengan status verifikasi per bagian. Visi, misi, sejarah, dan struktur organisasi belum ditampilkan karena belum ada sumber resmi.</li><li>Materi Gudang Teknik dari presentasi internal: pengertian, fungsi, jenis material, manajemen inventory, kode barang, administrasi stok, dan indikator kinerja.</li><li>Alur barang masuk, barang keluar, dan stock opname sebagai <strong>draf</strong>. Alur ini belum dicocokkan dengan gambar slide 5–6.</li><li>Enam SOP draf dari praktik umum pergudangan.</li><li>Empat tutorial dengan data latihan.</li><li>Pencarian lokal, breadcrumb, daftar isi, diagram, FAQ accordion, dan tampilan responsif.</li></ul><h2 id="cara-mencatat-versi-baru" tabindex="-1">Cara mencatat versi baru <a class="header-anchor" href="#cara-mencatat-versi-baru" aria-label="Permalink to &quot;Cara mencatat versi baru&quot;">​</a></h2><ol><li>Naikkan nomor <code>version</code> di <code>package.json</code>. Gunakan angka tengah untuk penambahan isi (0.2.0) dan angka akhir untuk perbaikan kecil (0.1.1).</li><li>Tambahkan bagian baru di atas halaman ini, berisi tanggal dan daftar perubahannya.</li></ol>',12)])])}const g=r(t,[["render",o]]);export{m as __pageData,g as default};
